      if (a.ground === "none") return { title: "Без одного из четырёх оснований МФЦ вернёт заявление.", text: "Проверьте на сайте ФССП, как окончено производство: нужен «п. 4 ч. 1 ст. 46». Если основания нет, возможно только банкротство через суд или договорённость с кредиторами." };
      if (a.ground === "returned" && a.new_ip === "yes") return { title: "Мешают новые исполнительные производства.", text: "Закон требует, чтобы после возврата исполнительного листа не было других неоконченных производств о взыскании денег (пп. 1 п. 1 ст. 223.2). МФЦ проверит это по сайту ФССП. Подать можно, когда они будут окончены." };
